(()=>{'use strict';
const toast=document.querySelector('.toast');let timer;
function inform(message){toast.textContent=message;toast.classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('visible'),2600);}
document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copy);inform('优惠码已复制，请在结算页确认折扣。');}catch{inform('未能自动复制，请手动选择优惠码。');}}));
const input=document.querySelector('#brand-search'),cards=[...document.querySelectorAll('[data-brand]')],filters=[...document.querySelectorAll('[data-filter]')];let filter='all';
function apply(){let count=0;for(const c of cards){const nameMatch=c.dataset.brand.toLowerCase().includes((input?.value||'').trim().toLowerCase());const match=filter==='all'||filter==='budget'&&Number(c.dataset.price)<=20||filter==='flow'&&Number(c.dataset.flow)>=150||filter==='time'&&c.dataset.time==='true';c.hidden=!(nameMatch&&match);if(!c.hidden)count++;}const label=document.querySelector('#results-label');if(label)label.textContent=`展示 ${count} 个品牌 · 参考价格，未独立确认当前在售`;const empty=document.querySelector('.empty');if(empty)empty.hidden=count!==0;}
input?.addEventListener('input',apply);filters.forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;filters.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});apply();}));
let sorted=false;document.querySelector('#sort-prices')?.addEventListener('click',event=>{const body=document.querySelector('.comparison-table tbody');const rows=[...body.rows];sorted=!sorted;rows.sort((a,b)=>(Number(a.dataset.price)-Number(b.dataset.price))*(sorted?1:-1));rows.forEach(row=>body.appendChild(row));event.currentTarget.textContent=sorted?'月付价格：从低到高':'月付价格：从高到低';});
const articleInput=document.querySelector('#article-search'),posts=[...document.querySelectorAll('[data-article]')],topicButtons=[...document.querySelectorAll('[data-topic-filter]')];let selectedTopic='all',articlePage=1;const pageSize=12,pager=document.querySelector('.article-index-pagination');
function filterArticles(reset=true){if(reset)articlePage=1;const q=(articleInput?.value||'').trim().toLowerCase(),matches=posts.filter(post=>post.dataset.article.toLowerCase().includes(q)&&(selectedTopic==='all'||post.dataset.topic===selectedTopic));const totalPages=Math.max(1,Math.ceil(matches.length/pageSize));articlePage=Math.min(articlePage,totalPages);posts.forEach(post=>post.hidden=true);matches.slice((articlePage-1)*pageSize,articlePage*pageSize).forEach(post=>post.hidden=false);const label=document.querySelector('#article-result-count');if(label)label.textContent=matches.length?'展示 '+((articlePage-1)*pageSize+1)+'–'+Math.min(articlePage*pageSize,matches.length)+' / '+matches.length+' 篇文章':'展示 0 / '+posts.length+' 篇文章';const empty=document.querySelector('#article-empty');if(empty)empty.hidden=matches.length!==0;if(pager){pager.hidden=totalPages<=1;document.querySelector('#article-previous').disabled=articlePage<=1;document.querySelector('#article-next').disabled=articlePage>=totalPages;const buttons=document.querySelector('#article-page-buttons');buttons.replaceChildren();for(let i=1;i<=totalPages;i++){const b=document.createElement('button');b.type='button';b.textContent=String(i);b.setAttribute('aria-label','第 '+i+' 页');if(i===articlePage)b.setAttribute('aria-current','page');b.addEventListener('click',()=>{articlePage=i;filterArticles(false);document.querySelector('.article-tools').scrollIntoView({block:'start',behavior:'auto'});});buttons.appendChild(b);}}}
articleInput?.addEventListener('input',()=>filterArticles());topicButtons.forEach(button=>button.addEventListener('click',()=>{selectedTopic=button.dataset.topicFilter;topicButtons.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});filterArticles();}));
if(articleInput){document.querySelector('#article-previous')?.addEventListener('click',()=>{articlePage--;filterArticles(false);document.querySelector('.article-tools').scrollIntoView({block:'start',behavior:'auto'});});document.querySelector('#article-next')?.addEventListener('click',()=>{articlePage++;filterArticles(false);document.querySelector('.article-tools').scrollIntoView({block:'start',behavior:'auto'});});filterArticles();}
if(window.matchMedia('(max-width:760px)').matches)document.querySelector('.article-topic-picker')?.removeAttribute('open');
document.querySelectorAll('.header nav a,.mobile-nav a').forEach(a=>{const target=new URL(a.href),here=location.pathname.replace(/index.html$/,''),there=target.pathname.replace(/index.html$/,'');if(!target.hash&&(here===there||there!=='/'&&here.startsWith(there)))a.setAttribute('aria-current',here===there?'page':'location');});
if(window.matchMedia('(max-width:760px)').matches)document.querySelector('.article-toc')?.removeAttribute('open');
})();
